/// <summary>
/// TMSEngine move it in contract class
/// <c>METTMSEngineService</c> Run the TMSEngine in batch for the given transferId
/// </summary>
class METTMSEngineService extends SysOperationServiceBase
{   

}

Method.Source:
/// <summary>
/// TMSEngine move it in service class update flag post execution
/// <c>METTMSEngineService</c> Run the TMSEngine in batch for the given Serviceclass
/// </summary>
public void postRunUpdateFlag(InventTransferTable _transfertable)
{
    METInventTransferTableExt transferTableExt;
    METTMSSHipmentOrderTable  shipmentOrderTable;

    ttsBegin;
    select forUpdate transferTableExt
                where transferTableExt.InventTransferTable == _transfertable.RecId;

    if (transferTableExt)
    {
        transferTableExt.TMSEngineBatchJobExecuted = NoYes::Yes;
        transferTableExt.update();
    }
    ttsCommit;

    // Post process verify shipment order created or not, if created then show success message 
    //with transferId, otherwise show completed message with transferId.
    select firstonly RecId from shipmentOrderTable
            where shipmentOrderTable.OrderNumber == _transfertable.TransferId;

    if (shipmentOrderTable.RecId != 0)
    {
        info(strFmt("@MET:TMSEngineSuccessMessage", _transfertable.TransferId));
    }
    else
    {
        info(strFmt("@MET:TMSEngineCompletedMessage", _transfertable.TransferId));
    }
}

/// <summary>
/// TMSEngine move it in service class
/// <c>METTMSEngineService</c> Run the TMSEngine in batch for the given Serviceclass
/// </summary>
public void processTMSEngineBacklog()
{
    InventTransferTable       transferTable;
    METInventTransferTableExt transferTableExt;
    METTMSSHipmentOrderTable  shipmentOrderTable;

    while select firstOnly10 transferTable
            order by transferTable.CreatedDateTime desc
            exists join transferTableExt
                where transferTableExt.InventTransferTable == transferTable.RecId
                   && transferTableExt.ReadyForTMSEngine == NoYes::Yes
                   && transferTableExt.TMSEngineBatchJobExecuted == NoYes::No
            notexists join shipmentOrderTable
                where shipmentOrderTable.OrderNumber == transferTable.TransferId
   {
        METTMSEngineOrderProccess process = METTMSEngineOrderProccess::construct(METTMSEngineExecutionMode::TransferOrderCreation,transferTable);
        process.run();

        this.postRunUpdateFlag(transferTable);
   }
}

/// <summary>
/// TMSEngine move it in service class
/// <c>METTMSEngineService</c> Run the TMSEngine in batch for the given Serviceclass
/// </summary>
/// <param name = "_contract">contract</param>
[SysEntryPointAttribute]
public void process(METTMSEngineContract _contract)
{
    METTMSSHipmentOrderTable  shipmentOrderTable;

    InventTransferTable transferTable =
        InventTransferTable::find(_contract.parmTransferId());


    METTMSEngineOrderProccess process = METTMSEngineOrderProccess::construct(METTMSEngineExecutionMode::TransferOrderCreation,transferTable);
    process.run();

    //Post process verify shipment order created or not, if created then show success message with transferId, otherwise show completed message with transferId.
    select firstonly RecId from shipmentOrderTable
            where shipmentOrderTable.OrderNumber == transferTable.TransferId;

    if (shipmentOrderTable.RecId != 0)
    {
        info(strFmt("@MET:TMSEngineSuccessMessage", transferTable.TransferId));
    }
    else
    {
        info(strFmt("@MET:TMSEngineCompletedMessage", transferTable.TransferId));
    }
}
